import type { Input } from "alchemy/Input";
import {
  consumeBusEvents,
  type EventRouteProps,
} from "../EventBridge/EventSource.vibe";

/** Keep the event source contract. */
export interface EventSourceProps extends EventRouteProps {
  mutable names?: readonly Input<string>[];
}

export const consumeEvents = <StreamReq = never, Req = never>(
  props: EventSourceProps,
  process: (events: readonly string[]) => void!never!Req,
) =>
  consumeBusEvents(
    props.names ?? [],
    process,
  );
